export const PROFESSORS = Array.from(new Set(articles.flatMap(a => a.professors ?? []))).sort();
export const LABS = Array.from(new Set(articles.flatMap(a => a.labs ?? []))).sort();
export const DEPARTMENTS = Array.from(new Set(articles.map(a => a.department).filter(Boolean) as string[])).sort();
export function getIssue(num: number) { return issues.find(i => i.number === num); }
export function getArticlesByIssue(num: number) { return articles.filter(a => a.issueNumber === num); }
export function getFeaturedArticles() { return articles.filter(a => a.featured); }
export function searchArticles(q: string) {
  const norm = (s: string) => s.toLowerCase().replace(/\s+/g, '');
  const nq = norm(q);
  if (!nq) return articles;
  return articles.filter(a =>
    norm(a.headline).includes(nq) || a.summary.some((p: string) => norm(p).includes(nq)) ||
    (a.professors ?? []).some((p: string) => norm(p).includes(nq)) ||
    (a.labs ?? []).some((l: string) => norm(l).includes(nq)) ||
    (a.author && norm(a.author).includes(nq)) || a.keyConcepts.some((k: string) => norm(k).includes(nq))
  );
}
